from author import begin, C, finish

begin("numbers")
C("Validate an inventory delta: an explicit plus or minus followed by exactly four ASCII digits. Nothing else is allowed.", r"[+-][0-9]{4}", "+0000|-0000|+0001|-0001|+1234|-9876|+9999|-9999", "0000|+000|+00000|++0000|+12a4|+１２３４", "The sign is mandatory and digit width is fixed.")
C("The counter field is a nonnegative base-ten integer ending in zero, with no leading zeros unless the entire field is zero.", r"(?:0|[1-9][0-9]*0)", "0|10|20|90|100|1230|9990|100000", "00|010|1|11|-10|10.0", "Zero is special; other values need both a nonzero start and a zero end.")
C("Accept a binary byte displayed as eight bits with one underscore after the fourth bit; spaces are not permitted.", r"[01]{4}_[01]{4}", "0000_0000|1111_1111|0000_1111|1111_0000|0101_1010|1000_0001|0011_1100|1010_0101", "000_0000|00000_0000|0000-0000|00000000|0000_0002|0000_ 0000", "The separator occupies a specific position.")
C("An instrument exports unsigned decimals with exactly three digits before the point and one after it. Leading zeros are required when needed; only ASCII digits are accepted.", r"[0-9]{3}\.[0-9]", "000.0|001.1|010.9|100.0|123.4|999.9|800.2|042.7", "00.0|0000.0|000.00|000,0|000x0|-000.0|a00.0", "The point is literal, and both widths matter.")
C("Accept a hexadecimal register value: lowercase prefix 0x followed by exactly six uppercase hexadecimal digits.", r"0x[0-9A-F]{6}", "0x000000|0xFFFFFF|0x123456|0xABCDEF|0x00FF00|0xA00001|0x999999|0x10AB20", "0XABCDEF|0xabcdef|0xABCDE|0xABCDEFG|0xG00000|ABCDEF", "Prefix case differs from digit case.")
C("A retry budget is an ASCII integer from 3 through 48 inclusive, without a sign or leading zeros.", r"(?:[3-9]|[1-3][0-9]|4[0-8])", "3|4|9|10|19|30|47|48", "2|49|03|+3|-3|3.0", "The endpoints are not a digit-count restriction.")
C("Store a signed decimal adjustment with one or two fractional digits. The integer part is zero or a nonzero digit followed by digits; plus is forbidden, and a minus is allowed except on a numerically zero amount.", r"(?!-0\.0{1,2}$)-?(?:0|[1-9][0-9]*)\.[0-9]{1,2}", "0.0|0.00|0.01|-0.01|1.2|-1.23|123.45|99.9", "-0.0|-0.00|01.2|+1.2|1|1.234|.12", "Negative zero includes both permitted fractional widths.")
C("A percentage field is 0 through 100 followed by percent, allowing one decimal digit only for values below 100. No leading zeros, sign, or spaces.", r"(?:(?:0|[1-9][0-9]?)(?:\.[0-9])?|100)%", "0%|0.0%|0.9%|1%|9.9%|99%|99.9%|100%", "101%|100.0%|01%|1.23%|+1%|1 %", "The top endpoint has no fractional spelling.")
C("Validate a positive decimal written in groups: one to three digits starting nonzero, then one or more comma groups of exactly three digits. No fractional part or whitespace.", r"[1-9][0-9]{0,2}(?:,[0-9]{3})+", "1,000|12,345|123,456|9,999|1,000,000|999,999,999|10,000|100,001", "0,001|01,000|1000,000|1,00|1,0000|1000|1,000.0", "Ungrouped and inconsistently grouped forms must fail.")
C("A power-of-ten label consists of lowercase e, an explicit sign, and an exponent from 0 to 24 without leading zeros.", r"e[+-](?:[0-9]|1[0-9]|2[0-4])", "e+0|e-0|e+1|e-9|e+10|e-19|e+23|e-24", "e+25|e-25|e+00|E+1|e1|e++1", "The exponent range and mandatory sign both apply.")
C("Find an ASCII integer from 10 to 39 immediately after lowercase sample= and immediately before a semicolon. Search anywhere; other text is unrestricted.", r"(?<=sample=)(?:[12][0-9]|3[0-9])(?=;)", "sample=10;|x sample=39; y|sample=20;|sample=19;tail|headsample=30;|sample=29;|sample=11;|a\nsample=38;\nz", "sample=9;|sample=40;|sample=010;|Sample=10;|sample=10 |sample=10|sample=1a;|sample=100;", "Context is exact; surrounding text must not become an anchor.", contains=True)
C("Search a note for a fraction token with numerator and denominator each from 1 to 9, separated by slash, and bounded on each side by start/end or a non-ASCII-alphanumeric character. ASCII letters or digits adjacent to the token invalidate that occurrence.", r"(?<![A-Za-z0-9])[1-9]\/[1-9](?![A-Za-z0-9])", "1/2|use 9/8 now|(3/4)|a:5/6;|7/1!|_2/3_|\n8/9\n|x 4/5 y", "0/2|1/0|10/2|1/22|a1/2|1/2z|1 /2|1/ 2", "Digit boundaries prevent matching pieces of larger fractions.", contains=True)
C("The dial setting is an unsigned multiple of five from 0 through 95. Use the shortest ASCII integer spelling, without units.", r"(?:[05]|[1-9][05])", "0|5|10|15|40|65|90|95", "00|05|1|96|100|-5|5.0", "A range alone does not enforce increments of five.")
C("A reconciliation pair is two identical unsigned integers separated by a colon. Each integer is zero or starts with a nonzero ASCII digit; signs and spaces are forbidden.", r"(0|[1-9][0-9]*):\1", "0:0|1:1|9:9|10:10|123:123|99:99|1000:1000|98765:98765", "1:2|10:010|01:01|0:00|1 :1|1:1:1", "Compare the entire decimal spelling, not just length.")
C("A mirrored four-digit access number repeats its first two digits in reverse order. All digits are ASCII; the first digit cannot be zero and the middle digit must differ from it.", r"([1-9])(?!\1)([0-9])\2\1", "1001|1221|2112|2332|3443|4554|9009|9889", "1111|0000|0110|1231|1222|12221|12a1", "The two captured digits have separate equality and inequality rules.")
C("Accept a canonical nonnegative rational in the form numerator/denominator. Numerator is 0 to 99, denominator 1 to 99, no leading zeros. If the numerator is zero the denominator must be 1; do not reduce or compare other fractions.", r"(?:0\/1|[1-9][0-9]?\/[1-9][0-9]?)", "0/1|1/1|1/99|99/1|99/99|2/4|10/20|45/9", "0/2|0/99|1/0|100/1|1/100|01/2|1/02", "Zero is canonicalized, but nonzero fractions need not be reduced.")
C("An ASCII decimal audit field has exactly six digits, is not all zeros, and has no adjacent repeated digit. Leading zeros are otherwise allowed.", r"(?!000000)(?![0-9]*([0-9])\1)[0-9]{6}", "012345|101010|909090|123456|987654|010203|120120|135790", "000000|112345|012244|123455|12345|1234567|12a456", "Nonzero and adjacency constraints are independent.")
C("A two-line numeric receipt uses LF only: first line is value= and an unsigned integer from 1 to 99; second line is copy= and the exact same digit spelling. No final LF, spaces or leading zeros.", r"value=([1-9][0-9]?)\ncopy=\1", "value=1\ncopy=1|value=9\ncopy=9|value=10\ncopy=10|value=99\ncopy=99|value=20\ncopy=20|value=34\ncopy=34|value=55\ncopy=55|value=78\ncopy=78", "value=1\ncopy=2|value=01\ncopy=01|value=0\ncopy=0|value=100\ncopy=100|value=1\r\ncopy=1|value=1 copy=1", "Line endings and repeated value are part of the format.")
C("For a scratchpad, accept the entire text when it starts with NUM{, ends with }NUM, and has between 1 and 40 Unicode code points inside. The interior may include any characters and line breaks but must include an ASCII digit. No text outside the wrapper.", r"NUM\{(?=.{1,40}\}NUM$)(?=.*[0-9]).*\}NUM", "NUM{0}NUM|NUM{a1}NUM|NUM{1\n2}NUM|NUM{é3}NUM|NUM{😀4}NUM|NUM{12345}NUM|NUM{1\t}NUM|NUM{" + "a"*39 + "1}NUM", "NUM{}NUM|NUM{abc}NUM|NUM{１２}NUM|NUM{" + "a"*40 + "1}NUM|num{1}NUM|NUM{1}num", "Count code points, include line breaks, and require an ASCII digit.", "su")
C("A calibration record is an integer 0 to 59, a separator chosen from colon or hyphen, then another integer 0 to 59 using the same separator before a third integer 0 to 59. Use shortest decimal spellings; the first and third integers must be identical and the middle must differ.", r"([0-9]|[1-5][0-9])([:-])(?!\1\2)(?:[0-9]|[1-5][0-9])\2\1", "0:1:0|1-0-1|59:58:59|58-59-58|9:10:9|10-9-10|20:30:20|30-20-30", "1:1:1|1:2:3|1:2-1|60:1:60|1:60:1|01:2:01|1:02:1", "Separator reuse, unequal middle, equal endpoints and range interact.")
finish()
